function nodeExternals(
	{ context, request }: ExternalItemFunctionData,
	callback: (
		err?: Error,
		result?: ExternalItemValue,
		type?: ExternalsType,
	) => void,
) {
	if (!/^(\.|\/)/.test(request || "")) {
		return callback(undefined, request);
	}

	callback();
}

/**
 * Generates a thin "external" stub that re-exports the entries of a globally
 * assigned bundle (e.g. `self.$scramjet`). Consumers that import the package
 * by its bare name pay zero source size — the stub is just a destructure of
 * the global.
 *
 * The export list is discovered automatically by parsing the already-emitted
 * bundle, so new exports flow through without any manual maintenance.
 */
class ExternalStubPlugin {
	bundleFilename: string;
	stubFilename: string;
	globalName: string;
	outputDir: string;

	constructor(opts: {
		bundleFilename: string;
		stubFilename: string;
		globalName: string;
		outputDir: string;
	}) {
		this.bundleFilename = opts.bundleFilename;
		this.stubFilename = opts.stubFilename;
		this.globalName = opts.globalName;
		this.outputDir = opts.outputDir;
	}
	private extractRuntimeExportNames(source: string): string[] {
		const names = new Set<string>();
	
		// ESM bundles end with `export { __webpack_exports__X as X, ... };`
		const esmMatches = source.matchAll(/export\s*\{([^}]+)\}\s*;/g);
		for (const m of esmMatches) {
			for (const part of m[1].split(",")) {
				const trimmed = part.trim();
				if (!trimmed) continue;
				const asMatch = trimmed.match(/\s+as\s+([A-Za-z_$][\w$]*)\s*$/);
				const name = asMatch
					? asMatch[1]
					: trimmed.match(/^([A-Za-z_$][\w$]*)/)?.[1];
				if (name) names.add(name);
			}
		}
		if (names.size > 0) return [...names];
	
		// Webpack IIFE bundles register entry exports via the *last*
		// `__webpack_require__.d(__webpack_exports__, { ... })` call. In
		// production builds those identifiers get minified (e.g. `r.d(o, {...})`),
		// so match any `<ident>.d(<ident>, { ... })` shape.
		const defMatches = [
			...source.matchAll(
				/\b[A-Za-z_$][\w$]*\.d\([A-Za-z_$][\w$]*,\s*\{([\s\S]*?)\}\)/g,
			),
		];
		if (defMatches.length > 0) {
			const last = defMatches[defMatches.length - 1][1];
			for (const m of last.matchAll(/([A-Za-z_$][\w$]*)\s*:/g)) {
				names.add(m[1]);
			}
		}
		return [...names];
	}
	
	private renderExternalStub(names: string[], globalName: string): string {
		const sorted = [...names].sort();
		return [
			"// AUTO-GENERATED by ExternalStubPlugin — do not edit.",
			`// Re-exports of globalThis.${globalName} (set by the IIFE bundle).`,
			`const __external = /** @type {any} */ (globalThis).${globalName};`,
			"export const {",
			...sorted.map((n) => `\t${n},`),
			"} = __external;",
			"",
		].join("\n");
	}
	
	apply(compiler: WebpackCompiler) {
		compiler.hooks.afterEmit.tap("ExternalStubPlugin", () => {
			const bundlePath = join(this.outputDir, this.bundleFilename);
			const stubPath = join(this.outputDir, this.stubFilename);
			let source: string;
			try {
				source = readFileSync(bundlePath, "utf-8");
			} catch (e: any) {
				console.error(
					`ExternalStubPlugin: cannot read ${bundlePath}: ${e.message}`,
				);
				return;
			}

			const names = this.extractRuntimeExportNames(source);
			if (names.length === 0) {
				console.warn(
					`ExternalStubPlugin: no exports discovered in ${bundlePath}; stub not written`,
				);
				return;
			}

			const stub = this.renderExternalStub(names, this.globalName);
			writeFileSync(stubPath, stub);
			console.log(
				`ExternalStubPlugin: wrote ${this.stubFilename} (${names.length} exports → globalThis.${this.globalName})`,
			);
		});
	}
}

/**
 * Creates a type-checker plugin for `dir` that both type-checks the package
 * and emits its declaration files using its `tsconfig.types.json`. Uses the
 * checker's build mode with `write-dts`, so only `.d.ts` (and `.tsbuildinfo`)
 * files are written to disk.
 */
const createTypeChecker = (
	dir: string,
	options: Pick<TsCheckerRspackPluginOptions, "issue"> = {},
) =>
	new TsCheckerRspackPlugin({
		typescript: {
			configFile: join(dir, "tsconfig.types.json"),
			build: true,
			mode: "write-dts",
		},
		...options,
	});

/**
 * The checker plugin doesn't rewrite TS path aliases in emitted declarations,
 * so chain `tsc-alias` after it. This runs once the checker reports issues
 * (i.e. after each declaration emit), with a guard for watch mode reruns.
 */
class TscAliasRewritePlugin {
	busy = false;
	rerun = false;
	configFile: string;

	constructor(configFile: string) {
		this.configFile = configFile;
	}

	apply(compiler: WebpackCompiler) {
		getPluginHooks(compiler).issues.tap("TscAliasRewritePlugin", () => {
			this.schedule();
			return [];
		});
	}

	private schedule() {
		if (this.busy) {
			this.rerun = true;
			return;
		}
		this.busy = true;
		replaceTscAliasPaths({ configFile: this.configFile })
			.catch((e) => console.error(`TscAliasRewritePlugin: ${e.message}`))
			.finally(() => {
				this.busy = false;
				if (this.rerun) {
					this.rerun = false;
					this.schedule();
				}
			});
	}
}

export const tsloader = {
	test: /\.ts$/,
	loader: "builtin:swc-loader",
	exclude: ["/node_modules/"],
	options: {
		jsc: {
			parser: {
				syntax: "typescript",
			},
			target: "es2022",
		},
		module: {
			type: "es6",
			strict: false,
			strictMode: false,
		},
	},
	type: "javascript/auto",
};
const rsDoctorPlugin = process.env.DEBUG
	? new RsdoctorRspackPlugin({
			supports: {
				parseBundle: true,
				banner: true,
			},
		})
	: null;
const createGenericConfig = (meta: any, options: Partial<RspackOptions>) => {
	const def = {
		devtool: "source-map",
		mode: "development" as Mode,
		resolve: {
			extensions: [".ts", ".js"],
		},
		module: {
			rules: [tsloader],
			parser: {
				javascript: {
					overrideStrict: "non-strict",
					dynamicImportMode: "eager",
				},
			},
		},
		plugins: [
			new rspack.DefinePlugin({
				VERSION: JSON.stringify(meta.version),
			}),
			new rspack.DefinePlugin({
				COMMITHASH: (() => {
					try {
						const hash = JSON.stringify(
							execSync("git rev-parse --short HEAD", {
								encoding: "utf-8",
							}).replace(/\r?\n|\r/g, ""),
						);

						return hash;
					} catch {
						return JSON.stringify("unknown");
					}
				})(),
			}),
			new rspack.DefinePlugin({
				BUILDDATE: JSON.stringify(new Date().toISOString()),
			}),
			rsDoctorPlugin
		],
		optimization: {
			minimizer: [
				new rspack.SwcJsMinimizerRspackPlugin({
					minimizerOptions: {
						module: options.output?.libraryTarget === "module",
					},
				}),
			],
		},
	};
	return defineConfig(merge<RspackOptions>(def as RspackOptions, options));
};

const scramjetdir = join(__dirname, "packages/core");
const scramjetmeta = JSON.parse(
	await readFile(join(scramjetdir, "package.json"), "utf-8"),
);
const wasmPath = join(scramjetdir, "dist/scramjet.wasm");
let wasmB64: string;
const wasmBuf = await readFile(wasmPath);
wasmB64 = wasmBuf.toString("base64");

type ScramjetBuildConfig = {
	name: string;
	entry: RspackOptions["entry"];
	output: RspackOptions["output"];
	rewriterWasm: string;
	extraConfig?: Partial<RspackOptions>;
};
// Common configuration options for scramjet builds
const createScramjetConfig = (options: ScramjetBuildConfig) => {
	const { name, entry, output, rewriterWasm, extraConfig = {} } = options;

	return createGenericConfig(scramjetmeta, {
		name,
		entry,
		resolve: {
			alias: {
				"@rewriters": join(scramjetdir, "src/shared/rewriters"),
				"@client": join(scramjetdir, "src/client"),
				"@": join(scramjetdir, "src"),
			},
		},
		output,
		plugins: [
			new rspack.ProvidePlugin({
				dbg: [join(scramjetdir, "src/log.ts"), "default"],
			}),
			new rspack.DefinePlugin({
				REWRITERWASM: rewriterWasm,
			})
		],
		target: "webworker",
		ignoreWarnings: [
			{
				module: /src\/entry\.ts/,
				message:
					/Critical dependency: the request of a dependency is an expression/,
			},
		],
		...extraConfig,
	});
};

// IIFE build that does NOT bundle the wasm, exposes global $scramjet
const iifeConfig = createScramjetConfig({
	name: "scramjet-iife",
	entry: {
		main: join(scramjetdir, "src/index.ts"),
	},
	output: {
		filename: "scramjet.js",
		path: join(scramjetdir, "dist"),
		iife: true,
		library: {
			type: "assign",
			name: "self.$scramjet",
		},
	},
	rewriterWasm: "undefined",
	extraConfig: {
		performance: {
			hints: false,
		},
	},
});

// IIFE build that BUNDLES the wasm and exposes global $scramjet
const iifeBundledConfig = createScramjetConfig({
	name: "scramjet-iife-bundled",
	entry: {
		bundled: join(scramjetdir, "src/index.ts"),
	},
	output: {
		filename: "scramjet_bundled.js",
		path: join(scramjetdir, "dist"),
		iife: true,
		library: {
			type: "assign",
			name: "self.$scramjet",
		},
	},
	rewriterWasm: JSON.stringify(wasmB64),
	extraConfig: {
		performance: {
			hints: false,
		},
	},
});

// Type-checking / declaration issues for core that are known to pre-date the
// migration to ts-checker-rspack-plugin (the old shell-out-to-tsc plugin
// silently swallowed these). Remove entries as the underlying errors get fixed.
const knownCoreIssues: Pick<TsCheckerRspackPluginOptions, "issue"> = {
	issue: {
		exclude: [
			{ severity: "error", file: "src/client/client.ts", code: "TS2339" },
			{ severity: "error", file: "src/client/shared/wrap.ts", code: "TS2740" },
			{ severity: "error", file: "src/fetch/headers.ts", code: "TS2352" },
			{ severity: "error", file: "src/fetch/index.ts", code: "TS2305" },
			{ severity: "error", file: "src/shared/mime.ts", code: "TS2345" },
			{ severity: "error", file: "src/shared/rewriters/js.ts", code: "TS2339" },
			{ severity: "error", file: "src/shared/rewriters/js.ts", code: "TS2345" },
			{
				severity: "error",
				file: "src/shared/rewriters/url.ts",
				code: "TS2322",
			},
		],
	},
};

// Type-check core and emit its declarations via the checker plugin, chained
// with tsc-alias to resolve path aliases in the generated .d.ts files.
// Attached only to this build to avoid running a checker worker per config.
iifeConfig.plugins!.push(
	createTypeChecker(scramjetdir, knownCoreIssues),
	new TscAliasRewritePlugin(join(scramjetdir, "tsconfig.types.json")),
);

// no wasm bundled, esmodule
const moduleConfig = createScramjetConfig({
	name: "scramjet-esmodule",
	entry: {
		bundle: join(scramjetdir, "src/index.ts"),
	},
	output: {
		filename: "scramjet.mjs",
		path: join(scramjetdir, "dist"),
		libraryTarget: "module",
		iife: false,
	},
	// do not embed the wasm in this build
	rewriterWasm: "undefined",
	extraConfig: {
		performance: {
			hints: false,
		},
		experiments: {
			outputModule: true,
		},
	},
});
moduleConfig.plugins!.push(
	new ExternalStubPlugin({
		bundleFilename: "scramjet.mjs",
		stubFilename: "scramjet-external.mjs",
		globalName: "$scramjet",
		outputDir: join(scramjetdir, "dist"),
	}),
);

// wasm bundled, esmodule
const moduleBundledConfig = createScramjetConfig({
	name: "scramjet-esmodule-bundled",
	entry: {
		bundle: join(scramjetdir, "src/index.ts"),
	},
	output: {
		filename: "scramjet_bundled.mjs",
		path: join(scramjetdir, "dist"),
		libraryTarget: "module",
		iife: false,
	},
	rewriterWasm: JSON.stringify(wasmB64),
	extraConfig: {
		performance: {
			hints: false,
		},
		experiments: {
			outputModule: true,
		},
	},
});

const controllerdir = join(__dirname, "packages/controller");
const controllermeta = JSON.parse(
	await readFile(join(controllerdir, "package.json"), "utf-8"),
);
const controllerVersionDefines = new rspack.DefinePlugin({
	SCRAMJET_EXPECTED_VERSION: JSON.stringify(scramjetmeta.version),
	CONTROLLER_VERSION: JSON.stringify(controllermeta.version),
});

const controllerConfig = createGenericConfig(controllermeta, {
	name: "scramjet-controller",
	dependencies: ["scramjet-esmodule"],
	entry: {
		api: join(controllerdir, "src/index.ts"),
		inject: join(controllerdir, "src/inject.ts"),
		sw: join(controllerdir, "src/sw.ts"),
	},
	output: {
		filename: "controller.[name].js",
		path: join(controllerdir, "dist"),
		iife: true,
		library: {
			type: "var",
			name: "$scramjetController",
		},
	},
	target: "web",
	plugins: [
		controllerVersionDefines,
		new ExternalStubPlugin({
			bundleFilename: "controller.api.js",
			stubFilename: "controller-external.mjs",
			globalName: "$scramjetController",
			outputDir: join(controllerdir, "dist"),
		}),
		createTypeChecker(controllerdir),
	],
});

const utilsdir = join(__dirname, "packages/utils");
